import { brotliDecompressSync } from 'node:zlib';

const BUNDLE_B64 = '';

const SUPABASE_URL =
  process.env.SUPABASE_URL ||
  'https://gfdtnjhqamtmxvlaaeoz.supabase.co';

const SUPABASE_PUBLISHABLE_KEY =
  process.env.SUPABASE_PUBLISHABLE_KEY ||
  'sb_publishable_7jBvCxY-xK4BTTAvEY0N9A_d7RqcEnu';

function getProtectedBundle() {
  const compressed = Buffer.from(BUNDLE_B64, 'base64');
  const json = brotliDecompressSync(compressed).toString('utf8');
  return JSON.parse(json);
}

export default async function handler(req, res) {
  res.setHeader('Cache-Control', 'no-store, max-age=0');
  res.setHeader('X-Content-Type-Options', 'nosniff');

  if (req.method !== 'GET') {
    res.setHeader('Allow', 'GET');
    return res.status(405).json({ error: 'method_not_allowed' });
  }

  const header = String(req.headers.authorization || '');
  const match = header.match(/^Bearer\s+(.+)$/i);

  if (!match) {
    return res.status(401).json({ error: 'unauthorized' });
  }

  const token = match[1];

  try {
    const userRes = await fetch(`${SUPABASE_URL}/auth/v1/user`, {
      headers: {
        apikey: SUPABASE_PUBLISHABLE_KEY,
        Authorization: `Bearer ${token}`
      }
    });

    if (!userRes.ok) {
      return res.status(401).json({ error: 'unauthorized' });
    }

    const accessRes = await fetch(
      `${SUPABASE_URL}/rest/v1/rpc/is_authorized_panel_user`,
      {
        method: 'POST',
        headers: {
          apikey: SUPABASE_PUBLISHABLE_KEY,
          Authorization: `Bearer ${token}`,
          Accept: 'application/json',
          'Content-Type': 'application/json'
        },
        body: '{}'
      }
    );

    if (!accessRes.ok) {
      const detail = await accessRes.text().catch(() => '');
      console.error('authorization rpc failed', accessRes.status, detail);

      return res.status(403).json({
        error: 'authorization_check_failed'
      });
    }

    const allowed = await accessRes.json();

    if (allowed !== true) {
      return res.status(403).json({ error: 'forbidden' });
    }

    return res.status(200).json(getProtectedBundle());
  } catch (error) {
    console.error('panel-bundle:', error);
    return res.status(500).json({ error: 'internal_error' });
  }
}
